25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * PTP time distribution PHC
33	 */
34	module ptp_td_phc #
35	(
36	    parameter PERIOD_NS_NUM = 32,
37	    parameter PERIOD_NS_DENOM = 5
38	)
39	(
40	    input  wire         clk,
41	    input  wire         rst,
42	
43	    /*
44	     * ToD timestamp control
45	     */
46	    input  wire [47:0]  input_ts_tod_s,
47	    input  wire [29:0]  input_ts_tod_ns,
48	    input  wire         input_ts_tod_valid,
49	    output wire         input_ts_tod_ready,
50	    input  wire [29:0]  input_ts_tod_offset_ns,
51	    input  wire         input_ts_tod_offset_valid,
52	    output wire         input_ts_tod_offset_ready,
53	
54	    /*
55	     * Relative timestamp control
56	     */
57	    input  wire [47:0]  input_ts_rel_ns,
58	    input  wire         input_ts_rel_valid,
59	    output wire         input_ts_rel_ready,
60	    input  wire [31:0]  input_ts_rel_offset_ns,
61	    input  wire         input_ts_rel_offset_valid,
62	    output wire         input_ts_rel_offset_ready,
63	
64	    /*
65	     * Fractional ns control
66	     */
67	    input  wire [31:0]  input_ts_offset_fns,
68	    input  wire         input_ts_offset_valid,
69	    output wire         input_ts_offset_ready,
70	
71	    /*
72	     * Period control
73	     */
74	    input  wire [7:0]   input_period_ns,
75	    input  wire [31:0]  input_period_fns,
76	    input  wire         input_period_valid,
77	    output wire         input_period_ready,
78	    input  wire [15:0]  input_drift_num,
79	    input  wire [15:0]  input_drift_denom,
80	    input  wire         input_drift_valid,
81	    output wire         input_drift_ready,
82	
83	    /*
84	     * Time distribution serial data output
85	     */
86	    output wire         ptp_td_sdo,
87	
88	    /*
89	     * PPS output
90	     */
91	    output wire         output_pps,
92	    output wire         output_pps_str
93	);
94	
95	localparam INC_NS_W = 9+8;
96	
97	localparam FNS_W = 32;
98	
99	localparam PERIOD_NS = PERIOD_NS_NUM / PERIOD_NS_DENOM;
100	localparam PERIOD_NS_REM = PERIOD_NS_NUM - PERIOD_NS*PERIOD_NS_DENOM;
101	localparam PERIOD_FNS = (PERIOD_NS_REM * {32'd1, {FNS_W{1'b0}}}) / PERIOD_NS_DENOM;
102	localparam PERIOD_FNS_REM = (PERIOD_NS_REM * {32'd1, {FNS_W{1'b0}}}) - PERIOD_FNS*PERIOD_NS_DENOM;
103	
104	localparam [30:0] NS_PER_S = 31'd1_000_000_000;
105	
106	reg [7:0] period_ns_reg = PERIOD_NS;
107	reg [FNS_W-1:0] period_fns_reg = PERIOD_FNS;
108	
109	reg [15:0] drift_num_reg = PERIOD_FNS_REM;
110	reg [15:0] drift_denom_reg = PERIOD_NS_DENOM;
111	reg [15:0] drift_cnt_reg = 0;
112	reg [15:0] drift_cnt_d1_reg = 0;
113	reg drift_apply_reg = 1'b0;
114	reg [23:0] drift_acc_reg = 0;
115	
116	reg [INC_NS_W-1:0] ts_inc_ns_reg = 0;
117	reg [FNS_W-1:0] ts_fns_reg = 0;
118	
119	reg [32:0] ts_rel_ns_inc_reg = 0;
120	reg [47:0] ts_rel_ns_reg = 0;
121	reg ts_rel_updated_reg = 1'b0;
122	
123	reg [47:0] ts_tod_s_reg = 0;
124	reg [29:0] ts_tod_ns_reg = 0;
125	reg ts_tod_updated_reg = 1'b0;
126	
127	reg [31:0] ts_tod_offset_ns_reg = 0;
128	
129	reg [47:0] ts_tod_alt_s_reg = 0;
130	reg [31:0] ts_tod_alt_offset_ns_reg = 0;
131	
132	reg [7:0] td_update_cnt_reg = 0;
133	reg td_update_reg = 1'b0;
134	reg [1:0] td_msg_i_reg = 0;
135	
136	reg input_ts_tod_ready_reg = 1'b0;
137	reg input_ts_tod_offset_ready_reg = 1'b0;
138	reg input_ts_rel_ready_reg = 1'b0;
139	reg input_ts_rel_offset_ready_reg = 1'b0;
140	reg input_ts_offset_ready_reg = 1'b0;
141	
142	reg [17*14-1:0] td_shift_reg = {17*14{1'b1}};
143	
144	reg [15:0] pps_gen_fns_reg = 0;
145	reg [9:0]  pps_gen_ns_inc_reg = 0;
146	reg [30:0] pps_gen_ns_reg = 31'h40000000;
147	
148	reg [9:0] pps_delay_reg = 0;
149	reg pps_reg = 0;
150	reg pps_str_reg = 0;
151	
152	reg [3:0] update_state_reg = 0;
153	
154	reg [47:0] adder_a_reg = 0;
155	reg [47:0] adder_b_reg = 0;
156	reg adder_cin_reg = 0;
157	reg [47:0] adder_sum_reg = 0;
158	reg adder_cout_reg = 0;
159	reg adder_busy_reg = 0;
160	
161	assign input_ts_tod_ready = input_ts_tod_ready_reg;
162	assign input_ts_tod_offset_ready = input_ts_tod_offset_ready_reg;
163	assign input_ts_rel_ready = input_ts_rel_ready_reg;
164	assign input_ts_rel_offset_ready = input_ts_rel_offset_ready_reg;
165	assign input_ts_offset_ready = input_ts_offset_ready_reg;
166	
167	assign input_period_ready = 1'b1;
168	assign input_drift_ready = 1'b1;
169	
170	assign output_pps = pps_reg;
171	assign output_pps_str = pps_str_reg;
172	
173	assign ptp_td_sdo = td_shift_reg[0];
174	
175	always @(posedge clk) begin
176	    drift_apply_reg <= 1'b0;
177	
178	    input_ts_tod_ready_reg <= 1'b0;
179	    input_ts_tod_offset_ready_reg <= 1'b0;
180	    input_ts_rel_ready_reg <= 1'b0;
181	    input_ts_rel_offset_ready_reg <= 1'b0;
182	    input_ts_offset_ready_reg <= 1'b0;
183	
184	    // update and message generation cadence
185	    {td_update_reg, td_update_cnt_reg} <= td_update_cnt_reg + 1;
186	
187	    // latch drift setting
188	    if (input_drift_valid) begin
189	        drift_num_reg <= input_drift_num;
190	        drift_denom_reg <= input_drift_denom;
191	    end
192	
193	    // drift
194	    if (drift_denom_reg) begin
195	        if (drift_cnt_reg == 0) begin
196	            drift_cnt_reg <= drift_denom_reg - 1;
197	            drift_apply_reg <= 1'b1;
198	        end else begin
199	            drift_cnt_reg <= drift_cnt_reg - 1;
200	        end
201	    end else begin
202	        drift_cnt_reg <= 0;
203	    end
204	
205	    drift_cnt_d1_reg <= drift_cnt_reg;
206	
207	    // drift accumulation
208	    if (drift_apply_reg) begin
209	        drift_acc_reg <= drift_acc_reg + drift_num_reg;
210	    end
211	
212	    // latch period setting
213	    if (input_period_valid) begin
214	        period_ns_reg <= input_period_ns;
215	        period_fns_reg <= input_period_fns;
216	    end
217	
218	    // PPS generation
219	    if (td_update_reg) begin
220	        {pps_gen_ns_inc_reg, pps_gen_fns_reg} <= {period_ns_reg, period_fns_reg[31:16]} + ts_fns_reg[31:16];
221	    end else begin
222	        {pps_gen_ns_inc_reg, pps_gen_fns_reg} <= {period_ns_reg, period_fns_reg[31:16]} + pps_gen_fns_reg;
223	    end
224	    pps_gen_ns_reg <= pps_gen_ns_reg + pps_gen_ns_inc_reg;
225	
226	    if (!pps_gen_ns_reg[30]) begin
227	        pps_delay_reg <= 14*17 + 32 + 240;
228	        pps_gen_ns_reg[30] <= 1'b1;
229	    end
230	
231	    pps_reg <= 1'b0;
232	
233	    if (ts_tod_ns_reg[29]) begin
234	        pps_str_reg <= 1'b0;
235	    end
236	
237	    if (pps_delay_reg) begin
238	        pps_delay_reg <= pps_delay_reg - 1;
239	        if (pps_delay_reg == 1) begin
240	            pps_reg <= 1'b1;
241	            pps_str_reg <= 1'b1;
242	        end
243	    end
244	
245	    // update state machine
246	    {adder_cout_reg, adder_sum_reg} <= adder_a_reg + adder_b_reg + adder_cin_reg;
247	    adder_busy_reg <= 1'b0;
248	
249	    // computes the following:
250	    // {ts_inc_ns_reg, ts_fns_reg} = drift_acc_reg + $signed(input_ts_offset_fns) + {period_ns_reg, period_fns_reg} * 256 + ts_fns_reg
251	    // ts_rel_ns_reg = ts_rel_ns_reg + ts_inc_ns_reg + $signed(input_ts_rel_offset_ns);
252	    // ts_tod_ns_reg = ts_tod_ns_reg + ts_inc_ns_reg + $signed(input_ts_tod_offset_ns);
253	    //   if that borrowed,
254	    //     ts_tod_ns_reg = ts_tod_ns_reg + NS_PER_S
255	    //     ts_tod_s_reg = ts_tod_s_reg - 1
256	    //   else
257	    //     pps_gen_ns_reg = ts_tod_ns_reg - NS_PER_S
258	    //       if that did not borrow,
259	    //         ts_tod_ns_reg = ts_tod_ns_reg - NS_PER_S
260	    //         ts_tod_s_reg = ts_tod_s_reg + 1
261	    // ts_tod_offset_ns_reg = ts_tod_ns_reg - ts_rel_ns_reg
262	    //   if ts_tod_ns_reg[29]
263	    //     ts_tod_alt_offset_ns_reg = ts_tod_offset_ns_reg - NS_PER_S
264	    //     ts_tod_alt_s_reg = ts_tod_s_reg + 1
265	    //   else
266	    //     ts_tod_alt_offset_ns_reg = ts_tod_offset_ns_reg + NS_PER_S
267	    //     ts_tod_alt_s_reg = ts_tod_s_reg - 1
268	
269	    if (!adder_busy_reg) begin
270	        case (update_state_reg)
271	            0: begin
272	                // idle
273	
274	                // set relative timestamp
275	                if (input_ts_rel_valid) begin
276	                    ts_rel_ns_reg <= input_ts_rel_ns;
277	                    input_ts_rel_ready_reg <= 1'b1;
278	                    ts_rel_updated_reg <= 1'b1;
279	                end
280	
281	                // set ToD timestamp
282	                if (input_ts_tod_valid) begin
283	                    ts_tod_s_reg <= input_ts_tod_s;
284	                    ts_tod_ns_reg <= input_ts_tod_ns;
285	                    input_ts_tod_ready_reg <= 1'b1;
286	                    ts_tod_updated_reg <= 1'b1;
287	                end
288	
289	                // compute period 1 - add drift and requested offset
290	                if (drift_apply_reg) begin
291	                    adder_a_reg <= drift_acc_reg + drift_num_reg;
292	                end else begin
293	                    adder_a_reg <= drift_acc_reg;
294	                end
295	                adder_b_reg <= input_ts_offset_valid ? $signed(input_ts_offset_fns) : 0;
296	                adder_cin_reg <= 0;
297	
298	                if (td_update_reg) begin
299	                    drift_acc_reg <= 0;
300	                    input_ts_offset_ready_reg <= input_ts_offset_valid;
301	                    update_state_reg <= 1;
302	                    adder_busy_reg <= 1'b1;
303	                end else begin
304	                    update_state_reg <= 0;
305	                end
306	            end
307	            1: begin
308	                // compute period 2 - add drift and offset to period
309	                adder_a_reg <= adder_sum_reg;
310	                adder_b_reg <= {period_ns_reg, period_fns_reg, 8'd0};
311	                adder_cin_reg <= 0;
312	
313	                update_state_reg <= 2;
314	                adder_busy_reg <= 1'b1;
315	            end
316	            2: begin
317	                // compute next fns
318	                adder_a_reg <= adder_sum_reg;
319	                adder_b_reg <= ts_fns_reg;
320	                adder_cin_reg <= 0;
321	
322	                update_state_reg <= 3;
323	                adder_busy_reg <= 1'b1;
324	            end
325	            3: begin
326	                // store fns
327	                {ts_inc_ns_reg, ts_fns_reg} <= {adder_cout_reg, adder_sum_reg};
328	
329	                // compute relative timestamp 1 - add previous value and increment
330	                adder_a_reg <= ts_rel_ns_reg;
331	                adder_b_reg <= {adder_cout_reg, adder_sum_reg} >> FNS_W; // ts_inc_ns_reg
332	                adder_cin_reg <= 0;
333	
334	                update_state_reg <= 4;
335	                adder_busy_reg <= 1'b1;
336	            end
337	            4: begin
338	                // compute relative timestamp 2 - add offset
339	                adder_a_reg <= adder_sum_reg;
340	                adder_b_reg <= 0;
341	                adder_cin_reg <= 0;
342	
343	                // offset relative timestamp if requested
344	                if (input_ts_rel_offset_valid) begin
345	                    adder_b_reg <= $signed(input_ts_rel_offset_ns);
346	                    input_ts_rel_offset_ready_reg <= 1'b1;
347	                    ts_rel_updated_reg <= 1'b1;
348	                end
349	
350	                update_state_reg <= 5;
351	                adder_busy_reg <= 1'b1;
352	            end
353	            5: begin
354	                // store relative timestamp
355	                ts_rel_ns_reg <= adder_sum_reg;
356	
357	                // compute ToD timestamp 1 - add previous value and increment
358	                adder_a_reg <= ts_tod_ns_reg;
359	                adder_b_reg <= ts_inc_ns_reg;
360	                adder_cin_reg <= 0;
361	
362	                update_state_reg <= 6;
363	                adder_busy_reg <= 1'b1;
364	            end
365	            6: begin
366	                // compute ToD timestamp 2 - add offset
367	                adder_a_reg <= adder_sum_reg;
368	                adder_b_reg <= 0;
369	                adder_cin_reg <= 0;
370	
371	                // offset ToD timestamp if requested
372	                if (input_ts_tod_offset_valid) begin
373	                    adder_b_reg <= $signed(input_ts_tod_offset_ns);
374	                    input_ts_tod_offset_ready_reg <= 1'b1;
375	                    ts_tod_updated_reg <= 1'b1;
376	                end
377	                
378	                update_state_reg <= 7;
379	                adder_busy_reg <= 1'b1;
380	            end
381	            7: begin
382	                // compute ToD timestamp 3 - check for underflow/overflow
383	                ts_tod_ns_reg <= adder_sum_reg;
384	
385	                if (adder_b_reg[47] && !adder_cout_reg) begin
386	                    // borrowed; add 1 billion
387	                    adder_a_reg <= adder_sum_reg;
388	                    adder_b_reg <= NS_PER_S;
389	                    adder_cin_reg <= 0;
390	
391	                    update_state_reg <= 8;
392	                    adder_busy_reg <= 1'b1;
393	                end else begin
394	                    // did not borrow; subtract 1 billion to check for overflow
395	                    adder_a_reg <= adder_sum_reg;
396	                    adder_b_reg <= -NS_PER_S;
397	                    adder_cin_reg <= 0;
398	
399	                    update_state_reg <= 9;
400	                    adder_busy_reg <= 1'b1;
401	                end
402	            end
403	            8: begin
404	                // seconds decrement
405	                ts_tod_ns_reg <= adder_sum_reg;
406	                pps_gen_ns_reg[30] <= 1'b1;
407	
408	                adder_a_reg <= ts_tod_s_reg;
409	                adder_b_reg <= -1;
410	                adder_cin_reg <= 0;
411	
412	                update_state_reg <= 10;
413	                adder_busy_reg <= 1'b1;
414	            end
415	            9: begin
416	                // seconds increment
417	                pps_gen_ns_reg <= adder_sum_reg;
418	
419	                if (!adder_cout_reg) begin
420	                    // borrowed; leave seconds alone
421	
422	                    adder_a_reg <= ts_tod_s_reg;
423	                    adder_b_reg <= 0;
424	                    adder_cin_reg <= 0;
425	                end else begin
426	                    // did not borrow; increment seconds
427	                    ts_tod_ns_reg <= adder_sum_reg;
428	
429	                    adder_a_reg <= ts_tod_s_reg;
430	                    adder_b_reg <= 1;
431	                    adder_cin_reg <= 0;
432	                end
433	
434	                update_state_reg <= 10;
435	                adder_busy_reg <= 1'b1;
436	            end
437	            10: begin
438	                // store seconds
439	                ts_tod_s_reg <= adder_sum_reg;
440	
441	                // compute offset
442	                adder_a_reg <= ts_tod_ns_reg;
443	                adder_b_reg <= ~ts_rel_ns_reg;
444	                adder_cin_reg <= 1;
445	
446	                update_state_reg <= 11;
447	                adder_busy_reg <= 1'b1;
448	            end
449	            11: begin
450	                // store offset
451	                ts_tod_offset_ns_reg <= adder_sum_reg;
452	
453	                adder_a_reg <= adder_sum_reg;
454	                adder_b_reg <= -NS_PER_S;
455	                adder_cin_reg <= 0;
456	
457	                if (ts_tod_ns_reg[29:27] == 3'b111) begin
458	                    // latter portion of second; compute offset for next second
459	                    adder_b_reg <= -NS_PER_S;
460	                    update_state_reg <= 12;
461	                    adder_busy_reg <= 1'b1;
462	                end else begin
463	                    // former portion of second; compute offset for previous second
464	                    adder_b_reg <= NS_PER_S;
465	                    update_state_reg <= 14;
466	                    adder_busy_reg <= 1'b1;
467	                end
468	            end
469	            12: begin
470	                // store alternate offset for next second
471	                ts_tod_alt_offset_ns_reg <= adder_sum_reg;
472	
473	                adder_a_reg <= ts_tod_s_reg;
474	                adder_b_reg <= 1;
475	                adder_cin_reg <= 0;
476	
477	                update_state_reg <= 13;
478	                adder_busy_reg <= 1'b1;
479	            end
480	            13: begin
481	                // store alternate second for next second
482	                ts_tod_alt_s_reg <= adder_sum_reg;
483	
484	                update_state_reg <= 0;
485	            end
486	            14: begin
487	                // store alternate offset for previous second
488	                ts_tod_alt_offset_ns_reg <= adder_sum_reg;
489	
490	                adder_a_reg <= ts_tod_s_reg;
491	                adder_b_reg <= -1;
492	                adder_cin_reg <= 0;
493	
494	                update_state_reg <= 15;
495	                adder_busy_reg <= 1'b1;
496	            end
497	            15: begin
498	                // store alternate second for previous second
499	                ts_tod_alt_s_reg <= adder_sum_reg;
500	
501	                update_state_reg <= 0;
502	            end
503	            default: begin
504	                // invalid state; return to idle
505	                update_state_reg <= 0;
506	            end
507	        endcase
508	    end
509	
510	    // time distribution message generation
511	    td_shift_reg <= {1'b1, td_shift_reg} >> 1;
512	
513	    if (td_update_reg) begin
514	        // word 0: control
515	        td_shift_reg[17*0+0 +: 1] <= 1'b0;
516	        td_shift_reg[17*0+1 +: 16] <= 0;
517	        td_shift_reg[17*0+1+0 +: 4] <= td_msg_i_reg;
518	        td_shift_reg[17*0+1+8 +: 1] <= ts_rel_updated_reg;
519	        td_shift_reg[17*0+1+9 +: 1] <= ts_tod_s_reg[0];
520	        ts_rel_updated_reg <= 1'b0;
521	
522	        case (td_msg_i_reg)
523	            2'd0: begin
524	                // msg 0 word 1: current ToD ns 15:0
525	                td_shift_reg[17*1+0 +: 1] <= 1'b0;
526	                td_shift_reg[17*1+1 +: 16] <= ts_tod_ns_reg[15:0];
527	                // msg 0 word 2: current ToD ns 29:16
528	                td_shift_reg[17*2+0 +: 1] <= 1'b0;
529	                td_shift_reg[17*2+1+0 +: 15] <= ts_tod_ns_reg[29:16];
530	                td_shift_reg[17*2+1+15 +: 1] <= ts_tod_updated_reg;
531	                ts_tod_updated_reg <= 1'b0;
532	                // msg 0 word 3: current ToD seconds 15:0
533	                td_shift_reg[17*3+0 +: 1] <= 1'b0;
534	                td_shift_reg[17*3+1 +: 16] <= ts_tod_s_reg[15:0];
535	                // msg 0 word 4: current ToD seconds 31:16
536	                td_shift_reg[17*4+0 +: 1] <= 1'b0;
537	                td_shift_reg[17*4+1 +: 16] <= ts_tod_s_reg[31:16];
538	                // msg 0 word 5: current ToD seconds 47:32
539	                td_shift_reg[17*5+0 +: 1] <= 1'b0;
540	                td_shift_reg[17*5+1 +: 16] <= ts_tod_s_reg[47:32];
541	                
542	                td_msg_i_reg <= 2'd1;
543	            end
544	            2'd1: begin
545	                // msg 1 word 1: current ToD ns offset 15:0
546	                td_shift_reg[17*1+0 +: 1] <= 1'b0;
547	                td_shift_reg[17*1+1 +: 16] <= ts_tod_offset_ns_reg[15:0];
548	                // msg 1 word 2: current ToD ns offset 31:16
549	                td_shift_reg[17*2+0 +: 1] <= 1'b0;
550	                td_shift_reg[17*2+1 +: 16] <= ts_tod_offset_ns_reg[31:16];
551	                // msg 1 word 3: drift num
552	                td_shift_reg[17*3+0 +: 1] <= 1'b0;
553	                td_shift_reg[17*3+1 +: 16] <= drift_num_reg;
554	                // msg 1 word 4: drift denom
555	                td_shift_reg[17*4+0 +: 1] <= 1'b0;
556	                td_shift_reg[17*4+1 +: 16] <= drift_denom_reg;
557	                // msg 1 word 5: drift state
558	                td_shift_reg[17*5+0 +: 1] <= 1'b0;
559	                td_shift_reg[17*5+1 +: 16] <= drift_cnt_d1_reg;
560	                
561	                td_msg_i_reg <= 2'd2;
562	            end
563	            2'd2: begin
564	                // msg 2 word 1: alternate ToD ns offset 15:0
565	                td_shift_reg[17*1+0 +: 1] <= 1'b0;
566	                td_shift_reg[17*1+1 +: 16] <= ts_tod_alt_offset_ns_reg[15:0];
567	                // msg 2 word 2: alternate ToD ns offset 31:16
568	                td_shift_reg[17*2+0 +: 1] <= 1'b0;
569	                td_shift_reg[17*2+1 +: 16] <= ts_tod_alt_offset_ns_reg[31:16];
570	                // msg 2 word 3: alternate ToD seconds 15:0
571	                td_shift_reg[17*3+0 +: 1] <= 1'b0;
572	                td_shift_reg[17*3+1 +: 16] <= ts_tod_alt_s_reg[15:0];
573	                // msg 2 word 4: alternate ToD seconds 31:16
574	                td_shift_reg[17*4+0 +: 1] <= 1'b0;
575	                td_shift_reg[17*4+1 +: 16] <= ts_tod_alt_s_reg[31:16];
576	                // msg 2 word 5: alternate ToD seconds 47:32
577	                td_shift_reg[17*5+0 +: 1] <= 1'b0;
578	                td_shift_reg[17*5+1 +: 16] <= ts_tod_alt_s_reg[47:32];
579	                
580	                td_msg_i_reg <= 2'd0;
581	            end
582	        endcase
583	
584	        // word 6: current fns 15:0
585	        td_shift_reg[17*6+0 +: 1] <= 1'b0;
586	        td_shift_reg[17*6+1 +: 16] <= ts_fns_reg[15:0];
587	        // word 7: current fns 31:16
588	        td_shift_reg[17*7+0 +: 1] <= 1'b0;
589	        td_shift_reg[17*7+1 +: 16] <= ts_fns_reg[31:16];
590	        // word 8: current ns 15:0
591	        td_shift_reg[17*8+0 +: 1] <= 1'b0;
592	        td_shift_reg[17*8+1 +: 16] <= ts_rel_ns_reg[15:0];
593	        // word 9: current ns 31:16
594	        td_shift_reg[17*9+0 +: 1] <= 1'b0;
595	        td_shift_reg[17*9+1 +: 16] <= ts_rel_ns_reg[31:16];
596	        // word 10: current ns 47:32
597	        td_shift_reg[17*10+0 +: 1] <= 1'b0;
598	        td_shift_reg[17*10+1 +: 16] <= ts_rel_ns_reg[47:32];
599	        // word 11: current phase increment fns 15:0
600	        td_shift_reg[17*11+0 +: 1] <= 1'b0;
601	        td_shift_reg[17*11+1 +: 16] <= period_fns_reg[15:0];
602	        // word 12: current phase increment fns 31:16
603	        td_shift_reg[17*12+0 +: 1] <= 1'b0;
604	        td_shift_reg[17*12+1 +: 16] <= period_fns_reg[31:16];
605	        // word 13: current phase increment ns 7:0 + crc
606	        td_shift_reg[17*13+0 +: 1] <= 1'b0;
607	        td_shift_reg[17*13+1 +: 16] <= period_ns_reg[7:0];
608	    end
609	
610	    if (rst) begin
611	        period_ns_reg <= PERIOD_NS;
612	        period_fns_reg <= PERIOD_FNS;
613	        drift_num_reg <= PERIOD_FNS_REM;
614	        drift_denom_reg <= PERIOD_NS_DENOM;
615	        drift_cnt_reg <= 0;
616	        drift_acc_reg <= 0;
617	        ts_fns_reg <= 0;
618	        ts_rel_ns_reg <= 0;
619	        ts_rel_updated_reg <= 0;
620	        ts_tod_s_reg <= 0;
621	        ts_tod_ns_reg <= 0;
622	        ts_tod_updated_reg <= 0;
623	
624	        pps_gen_ns_reg[30] <= 1'b1;
625	        pps_delay_reg <= 0;
626	        pps_reg <= 0;
627	        pps_str_reg <= 0;
628	
629	        td_update_cnt_reg <= 0;
630	        td_update_reg <= 1'b0;
631	        td_msg_i_reg <= 0;
632	
633	        td_shift_reg <= {17*14{1'b1}};
634	    end
635	end
636	
637	endmodule
638	
639	`resetall
