26	
27	`resetall
28	`timescale 1ns / 1fs
29	`default_nettype none
30	
31	/*
32	 * PTP time distribution leaf
33	 */
34	module ptp_td_leaf #
35	(
36	    parameter TS_REL_EN = 1,
37	    parameter TS_TOD_EN = 1,
38	    parameter TS_FNS_W = 16,
39	    parameter TS_REL_NS_W = 48,
40	    parameter TS_TOD_S_W = 48,
41	    parameter TS_REL_W = TS_REL_NS_W + TS_FNS_W,
42	    parameter TS_TOD_W = TS_TOD_S_W + 32 + TS_FNS_W,
43	    parameter TD_SDI_PIPELINE = 2
44	)
45	(
46	    input  wire                 clk,
47	    input  wire                 rst,
48	    input  wire                 sample_clk,
49	
50	    /*
51	     * PTP clock interface
52	     */
53	    input  wire                 ptp_clk,
54	    input  wire                 ptp_rst,
55	    input  wire                 ptp_td_sdi,
56	
57	    /*
58	     * Timestamp output
59	     */
60	    output wire [TS_REL_W-1:0]  output_ts_rel,
61	    output wire                 output_ts_rel_step,
62	    output wire [TS_TOD_W-1:0]  output_ts_tod,
63	    output wire                 output_ts_tod_step,
64	
65	    /*
66	     * PPS output (ToD format only)
67	     */
68	    output wire                 output_pps,
69	    output wire                 output_pps_str,
70	
71	    /*
72	     * Status
73	     */
74	    output wire                 locked
75	);
76	
77	localparam SYNC_DELAY = 32-2-TD_SDI_PIPELINE;
78	
79	localparam TS_NS_W = TS_REL_NS_W < 9 ? 9 : TS_REL_NS_W;
80	localparam TS_TOD_NS_W = 30;
81	localparam PERIOD_NS_W = 8;
82	
83	localparam FNS_W = 16;
84	
85	localparam CMP_FNS_W = 4;
86	localparam SRC_FNS_W = CMP_FNS_W+8;
87	
88	localparam LOG_RATE = 3;
89	
90	localparam PHASE_CNT_W = LOG_RATE;
91	localparam PHASE_ACC_W = PHASE_CNT_W+16;
92	localparam LOAD_CNT_W = 8-LOG_RATE-1;
93	
94	localparam LOG_SAMPLE_SYNC_RATE = 4;
95	localparam SAMPLE_ACC_W = LOG_SAMPLE_SYNC_RATE+2;
96	
97	localparam LOG_PHASE_ERR_RATE = 3;
98	localparam PHASE_ERR_ACC_W = LOG_PHASE_ERR_RATE+2;
99	
100	localparam DST_SYNC_LOCK_W = 5;
101	localparam FREQ_LOCK_W = 5;
102	localparam PTP_LOCK_W = 8;
103	
104	localparam TIME_ERR_INT_W = PERIOD_NS_W+FNS_W;
105	
106	localparam [30:0] NS_PER_S = 31'd1_000_000_000;
107	
108	// pipeline to facilitate long input path
109	wire ptp_td_sdi_pipe[0:TD_SDI_PIPELINE];
110	
111	assign ptp_td_sdi_pipe[0] = ptp_td_sdi;
112	
113	generate
114	
115	genvar n;
116	
117	for (n = 0; n < TD_SDI_PIPELINE; n = n + 1) begin : pipe_stage
118	
119	    (* shreg_extract = "no" *)
120	    reg ptp_td_sdi_reg = 0;
121	
122	    assign ptp_td_sdi_pipe[n+1] = ptp_td_sdi_reg;
123	
124	    always @(posedge ptp_clk) begin
125	        ptp_td_sdi_reg <= ptp_td_sdi_pipe[n];
126	    end
127	
128	end
129	
130	endgenerate
131	
132	// deserialize data
133	reg [15:0] td_shift_reg = 0;
134	reg [4:0] bit_cnt_reg = 0;
135	reg td_valid_reg = 1'b0;
136	reg [3:0] td_index_reg = 0;
137	reg [3:0] td_msg_reg = 0;
138	
139	reg [15:0] td_tdata_reg = 0;
140	reg td_tvalid_reg = 1'b0;
141	reg td_tlast_reg = 1'b0;
142	reg [7:0] td_tid_reg = 0;
143	reg td_sync_reg = 1'b0;
144	
145	always @(posedge ptp_clk) begin
146	    td_shift_reg <= {ptp_td_sdi_pipe[TD_SDI_PIPELINE], td_shift_reg[15:1]};
147	
148	    td_tvalid_reg <= 1'b0;
149	
150	    if (bit_cnt_reg) begin
151	        bit_cnt_reg <= bit_cnt_reg - 1;
152	    end else begin
153	        td_valid_reg <= 1'b0;
154	        if (td_valid_reg) begin
155	            td_tdata_reg <= td_shift_reg;
156	            td_tvalid_reg <= 1'b1;
157	            td_tlast_reg <= ptp_td_sdi_pipe[TD_SDI_PIPELINE];
158	            td_tid_reg <= {td_msg_reg, td_index_reg};
159	            if (td_index_reg == 0) begin
160	                td_msg_reg <= td_shift_reg[3:0];
161	                td_tid_reg[7:4] <= td_shift_reg[3:0];
162	            end
163	            td_index_reg <= td_index_reg + 1;
164	            td_sync_reg = !td_sync_reg;
165	        end
166	        if (ptp_td_sdi_pipe[TD_SDI_PIPELINE] == 0) begin
167	            bit_cnt_reg <= 16;
168	            td_valid_reg <= 1'b1;
169	        end else begin
170	            td_index_reg <= 0;
171	        end
172	    end
173	
174	    if (ptp_rst) begin
175	        bit_cnt_reg <= 0;
176	        td_valid_reg <= 1'b0;
177	
178	        td_tvalid_reg <= 1'b0;
179	    end
180	end
181	
182	// sync TD data
183	reg [15:0] dst_td_tdata_reg = 0;
184	reg dst_td_tvalid_reg = 1'b0;
185	reg [7:0] dst_td_tid_reg = 0;
186	
187	(* shreg_extract = "no" *)
188	reg td_sync_sync1_reg = 1'b0;
189	(* shreg_extract = "no" *)
190	reg td_sync_sync2_reg = 1'b0;
191	(* shreg_extract = "no" *)
192	reg td_sync_sync3_reg = 1'b0;
193	
194	always @(posedge clk) begin
195	    td_sync_sync1_reg <= td_sync_reg;
196	    td_sync_sync2_reg <= td_sync_sync1_reg;
197	    td_sync_sync3_reg <= td_sync_sync2_reg;
198	end
199	
200	always @(posedge clk) begin
201	    dst_td_tvalid_reg <= 1'b0;
202	
203	    if (td_sync_sync3_reg ^ td_sync_sync2_reg) begin
204	        dst_td_tdata_reg <= td_tdata_reg;
205	        dst_td_tvalid_reg <= 1'b1;
206	        dst_td_tid_reg <= td_tid_reg;
207	    end
208	
209	    if (rst) begin
210	        dst_td_tvalid_reg <= 1'b0;
211	    end
212	end
213	
214	// source clock and sync generation
215	reg [5:0] src_sync_delay_reg = 0;
216	reg src_load_reg = 1'b0;
217	
218	reg [PHASE_CNT_W-1:0] src_phase_reg = 0;
219	reg src_update_reg = 1'b0;
220	reg src_sync_reg = 1'b0;
221	reg src_marker_reg = 1'b0;
222	
223	reg [PERIOD_NS_W+32-1:0] src_period_reg = 0;
224	reg [PERIOD_NS_W+32-1:0] src_period_shadow_reg = 0;
225	
226	reg [9+SRC_FNS_W-1:0] src_ns_reg = 0;
227	reg [9+32-1:0] src_ns_shadow_reg = 0;
228	
229	always @(posedge ptp_clk) begin
230	    src_load_reg <= 1'b0;
231	
232	    {src_update_reg, src_phase_reg} <= src_phase_reg+1;
233	
234	    if (src_update_reg) begin
235	        src_ns_reg <= src_ns_reg + ({src_period_reg, {PHASE_CNT_W{1'b0}}} >> (32-SRC_FNS_W));
236	        src_sync_reg <= !src_sync_reg;
237	    end
238	
239	    // extract data
240	    if (td_tvalid_reg) begin
241	        if (td_tid_reg[3:0] == 4'd6) begin
242	            src_ns_shadow_reg[15:0] <= td_tdata_reg;
243	        end
244	        if (td_tid_reg[3:0] == 4'd7) begin
245	            src_ns_shadow_reg[31:16] <= td_tdata_reg;
246	        end
247	        if (td_tid_reg[3:0] == 4'd8) begin
248	            src_ns_shadow_reg[40:32] <= td_tdata_reg;
249	        end
250	        if (td_tid_reg[3:0] == 4'd11) begin
251	            src_period_shadow_reg[15:0] <= td_tdata_reg;
252	        end
253	        if (td_tid_reg[3:0] == 4'd12) begin
254	            src_period_shadow_reg[31:16] <= td_tdata_reg;
255	        end
256	        if (td_tid_reg[3:0] == 4'd13) begin
257	            src_period_shadow_reg[39:32] <= td_tdata_reg;
258	        end
259	    end
260	
261	    if (src_load_reg) begin
262	        src_ns_reg <= src_ns_shadow_reg >> (32-SRC_FNS_W);
263	        src_period_reg <= src_period_shadow_reg;
264	        src_sync_reg <= 1'b1;
265	        src_marker_reg <= !src_marker_reg;
266	    end
267	
268	    if (src_sync_delay_reg == 1) begin
269	        src_load_reg <= 1'b1;
270	        src_phase_reg <= 0;
271	    end
272	
273	    if (src_sync_delay_reg) begin
274	        src_sync_delay_reg <= src_sync_delay_reg - 1;
275	    end
276	
277	    if (td_tvalid_reg && td_tlast_reg) begin
278	        src_sync_delay_reg <= SYNC_DELAY;
279	    end
280	end
281	
282	reg [PERIOD_NS_W+FNS_W-1:0] period_ns_reg = 0, period_ns_next = 0;
283	
284	reg [9+CMP_FNS_W-1:0] dst_ns_capt_reg = 0;
285	reg [9+CMP_FNS_W-1:0] src_ns_sync_reg = 0;
286	
287	reg [FNS_W-1:0] ts_fns_lsb_reg = 0, ts_fns_lsb_next = 0;
288	reg [FNS_W-1:0] ts_fns_reg = 0, ts_fns_next = 0;
289	
290	reg [8:0] ts_rel_ns_lsb_reg = 0, ts_rel_ns_lsb_next = 0;
291	reg [TS_NS_W-1:0] ts_rel_ns_reg = 0, ts_rel_ns_next = 0;
292	reg ts_rel_step_reg = 1'b0, ts_rel_step_next;
293	
294	reg [TS_TOD_S_W-1:0] ts_tod_s_reg = 0, ts_tod_s_next = 0;
295	reg [TS_TOD_NS_W-1:0] ts_tod_ns_reg = 0, ts_tod_ns_next = 0;
296	reg [8:0] ts_tod_offset_ns_reg = 0, ts_tod_offset_ns_next = 0;
297	reg ts_tod_step_reg = 1'b0, ts_tod_step_next;
298	
299	reg pps_reg = 1'b0, pps_next;
300	reg pps_str_reg = 1'b0, pps_str_next;
301	
302	reg [PHASE_ACC_W-1:0] dst_phase_reg = {PHASE_ACC_W{1'b0}}, dst_phase_next;
303	reg [PHASE_ACC_W-1:0] dst_phase_inc_reg = {PHASE_ACC_W{1'b0}}, dst_phase_inc_next;
304	
305	reg dst_sync_reg = 1'b0;
306	reg dst_update_reg = 1'b0, dst_update_next = 1'b0;
307	
308	(* shreg_extract = "no" *)
309	reg src_sync_sync1_reg = 1'b0;
310	(* shreg_extract = "no" *)
311	reg src_sync_sync2_reg = 1'b0;
312	(* shreg_extract = "no" *)
313	reg src_sync_sync3_reg = 1'b0;
314	(* shreg_extract = "no" *)
315	reg src_marker_sync1_reg = 1'b0;
316	(* shreg_extract = "no" *)
317	reg src_marker_sync2_reg = 1'b0;
318	(* shreg_extract = "no" *)
319	reg src_marker_sync3_reg = 1'b0;
320	
321	(* shreg_extract = "no" *)
322	reg src_sync_sample_sync1_reg = 1'b0;
323	(* shreg_extract = "no" *)
324	reg src_sync_sample_sync2_reg = 1'b0;
325	(* shreg_extract = "no" *)
326	reg src_sync_sample_sync3_reg = 1'b0;
327	(* shreg_extract = "no" *)
328	reg dst_sync_sample_sync1_reg = 1'b0;
329	(* shreg_extract = "no" *)
330	reg dst_sync_sample_sync2_reg = 1'b0;
331	(* shreg_extract = "no" *)
332	reg dst_sync_sample_sync3_reg = 1'b0;
333	
334	reg [SAMPLE_ACC_W-1:0] sample_acc_reg = 0;
335	reg [SAMPLE_ACC_W-1:0] sample_acc_out_reg = 0;
336	reg [LOG_SAMPLE_SYNC_RATE-1:0] sample_cnt_reg = 0;
337	reg sample_update_reg = 1'b0;
338	reg sample_update_sync1_reg = 1'b0;
339	reg sample_update_sync2_reg = 1'b0;
340	reg sample_update_sync3_reg = 1'b0;
341	
342	// CDC logic
343	always @(posedge clk) begin
344	    src_sync_sync1_reg <= src_sync_reg;
345	    src_sync_sync2_reg <= src_sync_sync1_reg;
346	    src_sync_sync3_reg <= src_sync_sync2_reg;
347	    src_marker_sync1_reg <= src_marker_reg;
348	    src_marker_sync2_reg <= src_marker_sync1_reg;
349	    src_marker_sync3_reg <= src_marker_sync2_reg;
350	end
351	
352	always @(posedge sample_clk) begin
353	    src_sync_sample_sync1_reg <= src_sync_reg;
354	    src_sync_sample_sync2_reg <= src_sync_sample_sync1_reg;
355	    src_sync_sample_sync3_reg <= src_sync_sample_sync2_reg;
356	    dst_sync_sample_sync1_reg <= dst_sync_reg;
357	    dst_sync_sample_sync2_reg <= dst_sync_sample_sync1_reg;
358	    dst_sync_sample_sync3_reg <= dst_sync_sample_sync2_reg;
359	end
360	
361	reg edge_1_reg = 1'b0;
362	reg edge_2_reg = 1'b0;
363	
364	reg [3:0] active_reg = 0;
365	
366	always @(posedge sample_clk) begin
367	    // phase and frequency detector
368	    if (dst_sync_sample_sync2_reg && !dst_sync_sample_sync3_reg) begin
369	        if (src_sync_sample_sync2_reg && !src_sync_sample_sync3_reg) begin
370	            edge_1_reg <= 1'b0;
371	            edge_2_reg <= 1'b0;
372	        end else begin
373	            edge_1_reg <= !edge_2_reg;
374	            edge_2_reg <= 1'b0;
375	        end
376	    end else if (src_sync_sample_sync2_reg && !src_sync_sample_sync3_reg) begin
377	        edge_1_reg <= 1'b0;
378	        edge_2_reg <= !edge_1_reg;
379	    end
380	
381	    // accumulator
382	    sample_acc_reg <= $signed(sample_acc_reg) + $signed({1'b0, edge_2_reg}) - $signed({1'b0, edge_1_reg});
383	
384	    sample_cnt_reg <= sample_cnt_reg + 1;
385	
386	    if (src_sync_sample_sync2_reg && !src_sync_sample_sync3_reg) begin
387	        active_reg[0] <= 1'b1;
388	    end
389	
390	    if (sample_cnt_reg == 0) begin
391	        active_reg <= {active_reg, src_sync_sample_sync2_reg && !src_sync_sample_sync3_reg};
392	        sample_acc_reg <= $signed({1'b0, edge_2_reg}) - $signed({1'b0, edge_1_reg});
393	        sample_acc_out_reg <= sample_acc_reg;
