849	        end else begin
850	            if (&freq_lock_count_reg) begin
851	                freq_locked_next = 1'b1;
852	            end else begin
853	                freq_lock_count_next = freq_lock_count_reg + 1;
854	            end
855	        end
856	
857	        if (!freq_locked_reg) begin
858	            ts_ns_diff_next = $signed(phase_err_out_reg) * 16 * 2**CMP_FNS_W;
859	            ts_ns_diff_valid_next = 1'b1;
860	        end
861	    end
862	
863	    if (ts_ns_diff_valid_reg) begin
864	        // PI control
865	
866	        // gain scheduling
867	        casez (ts_ns_diff_reg[9+CMP_FNS_W-5 +: 5])
868	            5'b01zzz: gain_sel_next = 1'b1;
869	            5'b001zz: gain_sel_next = 1'b1;
870	            5'b0001z: gain_sel_next = 1'b1;
871	            5'b00001: gain_sel_next = 1'b1;
872	            5'b00000: gain_sel_next = 1'b0;
873	            5'b11111: gain_sel_next = 1'b0;
874	            5'b11110: gain_sel_next = 1'b1;
875	            5'b1110z: gain_sel_next = 1'b1;
876	            5'b110zz: gain_sel_next = 1'b1;
877	            5'b10zzz: gain_sel_next = 1'b1;
878	            default: gain_sel_next = 1'b0;
879	        endcase
880	
881	        // time integral of error
882	        case (gain_sel_reg)
883	            1'b0: {ptp_ovf, time_err_int_next} = $signed({1'b0, time_err_int_reg}) + ($signed(ts_ns_diff_reg) / 2**4);
884	            1'b1: {ptp_ovf, time_err_int_next} = $signed({1'b0, time_err_int_reg}) + ($signed(ts_ns_diff_reg) * 2**2);
885	        endcase
886	
887	        // saturate
888	        if (ptp_ovf[1]) begin
889	            // sign bit set indicating underflow across zero; saturate to zero
890	            time_err_int_next = {TIME_ERR_INT_W{1'b0}};
891	        end else if (ptp_ovf[0]) begin
892	            // sign bit clear but carry bit set indicating overflow; saturate to all 1
893	            time_err_int_next = {TIME_ERR_INT_W{1'b1}};
894	        end
895	
896	        // compute output
897	        case (gain_sel_reg)
898	            1'b0: {ptp_ovf, period_ns_next} = $signed({1'b0, time_err_int_reg}) + ($signed(ts_ns_diff_reg) * 2**2);
899	            1'b1: {ptp_ovf, period_ns_next} = $signed({1'b0, time_err_int_reg}) + ($signed(ts_ns_diff_reg) * 2**6);
900	        endcase
901	
902	        // saturate
903	        if (ptp_ovf[1]) begin
904	            // sign bit set indicating underflow across zero; saturate to zero
905	            period_ns_next = {PERIOD_NS_W+FNS_W{1'b0}};
906	        end else if (ptp_ovf[0]) begin
907	            // sign bit clear but carry bit set indicating overflow; saturate to all 1
908	            period_ns_next = {PERIOD_NS_W+FNS_W{1'b1}};
909	        end
910	
911	        // adjust period if integrator is saturated
912	        if (time_err_int_reg == 0) begin
913	            period_ns_next = {PERIOD_NS_W+FNS_W{1'b0}};
914	        end else if (~time_err_int_reg == 0) begin
915	            period_ns_next = {PERIOD_NS_W+FNS_W{1'b1}};
916	        end
917	
918	        // locked status
919	        if (!freq_locked_reg) begin
920	            ptp_lock_count_next = 0;
921	            ptp_locked_next = 1'b0;
922	        end else if (gain_sel_reg == 1'b0) begin
923	            if (&ptp_lock_count_reg) begin
924	                ptp_locked_next = 1'b1;
925	            end else begin
926	                ptp_lock_count_next = ptp_lock_count_reg + 1;
927	            end
928	        end else begin
929	            if (ptp_lock_count_reg) begin
930	                ptp_lock_count_next = ptp_lock_count_reg - 1;
931	            end else begin
932	                ptp_locked_next = 1'b0;
933	            end
934	        end
935	    end
936	end
937	
938	always @(posedge clk) begin
939	    period_ns_reg <= period_ns_next;
940	
941	    ts_fns_lsb_reg <= ts_fns_lsb_next;
942	    ts_fns_reg <= ts_fns_next;
943	
944	    ts_rel_ns_lsb_reg <= ts_rel_ns_lsb_next;
945	    ts_rel_ns_reg <= ts_rel_ns_next;
946	    ts_rel_step_reg <= ts_rel_step_next;
947	
948	    ts_tod_s_reg <= ts_tod_s_next;
949	    ts_tod_ns_reg <= ts_tod_ns_next;
950	    ts_tod_offset_ns_reg <= ts_tod_offset_ns_next;
951	    ts_tod_step_reg <= ts_tod_step_next;
952	
953	    dst_rel_step_shadow_reg <= dst_rel_step_shadow_next;
954	    dst_rel_ns_shadow_reg <= dst_rel_ns_shadow_next;
955	    dst_rel_shadow_valid_reg <= dst_rel_shadow_valid_next;
956	
957	    dst_tod_step_shadow_reg <= dst_tod_step_shadow_next;
958	    dst_tod_ns_shadow_reg <= dst_tod_ns_shadow_next;
959	    dst_tod_s_shadow_reg <= dst_tod_s_shadow_next;
960	    dst_tod_shadow_valid_reg <= dst_tod_shadow_valid_next;
961	
962	    ts_rel_diff_reg <= ts_rel_diff_next;
963	    ts_rel_diff_valid_reg <= ts_rel_diff_valid_next;
964	    ts_rel_mismatch_cnt_reg <= ts_rel_mismatch_cnt_next;
965	    ts_rel_load_ts_reg <= ts_rel_load_ts_next;
966	
967	    ts_tod_diff_reg <= ts_tod_diff_next;
968	    ts_tod_diff_valid_reg <= ts_tod_diff_valid_next;
969	    ts_tod_mismatch_cnt_reg <= ts_tod_mismatch_cnt_next;
970	    ts_tod_load_ts_reg <= ts_tod_load_ts_next;
971	
972	    ts_ns_diff_reg <= ts_ns_diff_next;
973	    ts_ns_diff_valid_reg <= ts_ns_diff_valid_next;
974	
975	    time_err_int_reg <= time_err_int_next;
976	
977	    freq_lock_count_reg <= freq_lock_count_next;
978	    freq_locked_reg <= freq_locked_next;
979	    ptp_lock_count_reg <= ptp_lock_count_next;
980	    ptp_locked_reg <= ptp_locked_next;
981	
982	    gain_sel_reg <= gain_sel_next;
983	
984	    pps_reg <= pps_next;
985	    pps_str_reg <= pps_str_next;
986	
987	    if (rst) begin
988	        period_ns_reg <= 0;
989	        ts_fns_lsb_reg <= 0;
990	        ts_fns_reg <= 0;
991	        ts_rel_ns_lsb_reg <= 0;
992	        ts_rel_ns_reg <= 0;
993	        ts_rel_step_reg <= 1'b0;
994	        ts_tod_s_reg <= 0;
995	        ts_tod_ns_reg <= 0;
996	        ts_tod_step_reg <= 1'b0;
997	        dst_rel_shadow_valid_reg <= 1'b0;
998	        pps_reg <= 1'b0;
999	        pps_str_reg <= 1'b0;
1000	
1001	        ts_rel_diff_reg <= 1'b0;
1002	        ts_rel_diff_valid_reg <= 1'b0;
1003	        ts_rel_mismatch_cnt_reg <= 0;
1004	        ts_rel_load_ts_reg <= 0;
1005	
1006	        ts_tod_diff_reg <= 1'b0;
1007	        ts_tod_diff_valid_reg <= 1'b0;
1008	        ts_tod_mismatch_cnt_reg <= 0;
1009	        ts_tod_load_ts_reg <= 0;
1010	
1011	        ts_ns_diff_valid_reg <= 1'b0;
1012	
1013	        time_err_int_reg <= 0;
1014	
1015	        freq_lock_count_reg <= 0;
1016	        freq_locked_reg <= 1'b0;
1017	        ptp_lock_count_reg <= 0;
1018	        ptp_locked_reg <= 1'b0;
1019	    end
1020	end
1021	
1022	endmodule
1023	
